const e="/api";async function a(t,r=6){const o=await fetch(`${e}/start`,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({topic:t.trim(),max_rounds:r})});if(!o.ok){const n=await o.json().catch(()=>({}));throw new Error(n.error||`Start failed: ${o.status}`)}return o.json()}async function s(){const t=await fetch(`${e}/state`);if(!t.ok)throw new Error("Failed to get state");return t.json()}async function i(t=null){const r=`${e}/summary`,o=t!=null?{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify({override_audience:t})}:{},n=await fetch(r,o);if(!n.ok)throw new Error("Failed to get summary");return n.json()}export{s as getState,i as getSummary,a as startDebate};
